import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ethers } from 'ethers';
import { TransactionInterceptorService } from '@services/transaction-interceptor.service';
import { TxSignPayload, OfflineOpType, OfflineRequest } from '@services/ops.service';
import { ToastService } from '@services/toast.service';
import { QrCodeComponent } from '@components/ui/qr-code/qr-code.component';
import { OfflineWorkflowComponent } from '@components/ui/offline-workflow/offline-workflow.component';
import { IconComponent } from '@components/ui/icon/icon.component';
import { LoggerService } from "@services/logger.service";
import { ContractService } from '@services/contract.service';
import { ActivityService } from '@core/services/activity.service';
import { ActivityType, generateActivityId } from '@models/activity.model';

@Component({
    selector: 'app-tx-broadcast',
    standalone: true,
    imports: [CommonModule, FormsModule, QrCodeComponent, OfflineWorkflowComponent, IconComponent, TranslateModule],
    templateUrl: './tx-broadcast.component.html',
    styleUrls: ['./tx-broadcast.component.css']
})
export class TxBroadcastComponent implements OnInit, OnDestroy {
    unsignedTx: TxSignPayload | TxSignPayload[] | null = null;
    unsignedTxJson = '';
    signedRawTx: string | string[] = '';
    broadcastedTxHash = '';

    // Batch broadcast state
    isBatchMode = false;
    isBroadcastingBatch = false;
    batchTotal = 0;
    batchCurrentIndex = 0;
    batchBroadcastStatuses: { hash?: string, status: 'pending' | 'broadcasting' | 'mined' | 'error', error?: string }[] = [];
    batchFinalReceipt: ethers.TransactionReceipt | null = null;

    // Removed showScanner since OfflineWorkflow handles its own scanner state
    isBroadcasting = false;

    constructor(
        private txInterceptor: TransactionInterceptorService,
        private toastService: ToastService,
        private router: Router,
        private translate: TranslateService,
        private location: Location, private logger: LoggerService,
        private contractService: ContractService,
        private activityService: ActivityService
    ) { }

    ngOnInit() {
        this.logger.debug('[TxBroadcastComponent] initialized');
        this.unsignedTx = this.txInterceptor.getCurrentUnsignedTx();

        if (!this.unsignedTx) {
            this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.NO_TX_TO_BROADCAST'));
            this.router.navigate(['/']);
            return;
        }

        this.isBatchMode = Array.isArray(this.unsignedTx);

        // Build offline request format
        let request: OfflineRequest;

        if (this.isBatchMode) {
            const txs = this.unsignedTx as TxSignPayload[];
            request = {
                version: '2.0',
                type: 'REQUEST',
                operation: OfflineOpType.BATCHED_REQUESTS,
                chainId: txs[0].chainId, // Assume homogenous chainId
                contractAddress: txs[0].to,
                data: {
                    requests: txs.map(tx => {
                        const txData = { ...tx } as any;
                        // Strip huge unused properties to save QR space
                        delete txData.suggestedOfflineSender;
                        if (txData.metadata) {
                            delete txData.metadata.args;
                        }
                        return {
                            operation: OfflineOpType.TX_SIGN,
                            data: txData
                        };
                    })
                },
                timestamp: Date.now()
            };
        } else {
            const tx = this.unsignedTx as TxSignPayload;
            request = {
                version: '2.0',
                type: 'REQUEST',
                operation: OfflineOpType.TX_SIGN,
                chainId: tx.chainId,
                contractAddress: tx.to,
                data: tx,
                timestamp: Date.now()
            };
        }
        // Use compact JSON format to minimize QR code size and avoid payload limits
        this.unsignedTxJson = JSON.stringify(request);
    }

    copyJson() {
        navigator.clipboard.writeText(this.unsignedTxJson);
        this.toastService.success(this.translate.instant('TX_BROADCAST.SUCCESS.COPIED'));
    }

    // Removed toggleScanner as it's handled internally by OfflineWorkflow

    onSignatureReceived(data: string) {
        try {
            const response = JSON.parse(data);

            if (this.isBatchMode) {
                if (response.operation !== OfflineOpType.BATCHED_REQUESTS) {
                    this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.INVALID_QR_WRONG_OP'));
                    return;
                }

                if (!response.data?.responses || !Array.isArray(response.data.responses) || response.data.responses.length === 0) {
                    this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.INVALID_RESPONSE_MISSING_RAWTX'));
                    return;
                }

                // Extract rawTx from each response in the batch
                const rawTxs = response.data.responses.map((r: any) => {
                    if (typeof r === 'string') {
                        // Sometimes the tablet sends the stringified JSON or hex directly in the array
                        try {
                            const parsed = JSON.parse(r);
                            return parsed.rawTx || parsed.data?.rawTx || r;
                        } catch {
                            return r;
                        }
                    }
                    return r.rawTx || r.data?.rawTx;
                });

                if (rawTxs.some((tx: any) => !tx || (typeof tx === 'string' && !tx.startsWith('0x')))) {
                    this.toastService.error('Missing or invalid rawTx (must start with 0x) in batched responses');
                    return;
                }

                this.signedRawTx = rawTxs;

            } else {
                if (response.operation !== OfflineOpType.TX_SIGN) {
                    this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.INVALID_QR_WRONG_OP'));
                    return;
                }

                if (!response.rawTx) {
                    this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.INVALID_RESPONSE_MISSING_RAWTX'));
                    return;
                }

                this.signedRawTx = response.rawTx;
            }

            this.toastService.success(this.translate.instant('TX_BROADCAST.SUCCESS.SIGNED_RECEIVED'));
        } catch (e) {
            this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.FAILED_TO_PARSE_QR'));
        }
    }

    async broadcast() {
        if (!this.signedRawTx) {
            this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.NO_SIGNED_TX'));
            return;
        }

        if (Array.isArray(this.signedRawTx)) {
            return this.broadcastBatch(this.signedRawTx);
        }

        this.isBroadcasting = true;

        try {
            // Parse the signed tx if it's a JSON response object
            let rawTx = (this.signedRawTx as string).trim();

            // Check if user pasted the full JSON response instead of just the rawTx
            if (rawTx.startsWith('{')) {
                try {
                    const response = JSON.parse(rawTx);

                    // Handle BATCHED_REQUESTS payload specifically
                    if (response.operation === OfflineOpType.BATCHED_REQUESTS && response.data?.responses?.length > 0) {
                        this.toastService.info(this.translate.instant('TX_BROADCAST.INFO.EXTRACTED_RAWTX'));
                        const rawTxs = response.data.responses.map((r: any) => r.rawTx || r.data?.rawTx || r);
                        this.signedRawTx = rawTxs; // save the parsed array for UI feedback
                        return this.broadcastBatch(rawTxs);
                    }

                    // Standard single tx payload
                    if (response.rawTx) {
                        rawTx = response.rawTx;
                        this.signedRawTx = rawTx; // save the extracted string so it shows stripped in the UI
                        this.toastService.info(this.translate.instant('TX_BROADCAST.INFO.EXTRACTED_RAWTX'));
                    }
                } catch (e) {
                    // Not JSON, assume it's the raw tx directly
                }
            }

            return this.broadcastBatch([rawTx]);

        } catch (e: any) {
            this.handleBroadcastError(e);
        } finally {
            this.isBroadcasting = false;
        }
    }

    private mapOperationToActivityType(operation?: string): ActivityType {
        if (!operation) return 'EXECUTE_OPERATION';
        const op = operation.toUpperCase();
        if (op.includes('CREATE LOCKER')) return 'CREATE_LOCKER';
        if (op.includes('CREATE LOCK')) return 'CREATE_LOCK';
        if (op.includes('ADD TO LOCK') || op.includes('ADD TOKEN')) return 'ADD_TO_LOCK';
        if (op.includes('VESTING UNLOCK')) return 'VESTING_UNLOCK';
        if (op.includes('UNLOCK')) return 'UNLOCK';
        if (op.includes('CHANGE OWNER')) return 'CHANGE_OWNER';
        if (op.includes('ADD SIGNER')) return 'ADD_SIGNER';
        if (op.includes('REMOVE SIGNER')) return 'REMOVE_SIGNER';
        if (op.includes('BATCH UPDATE')) return 'BATCH_UPDATE_SIGNERS';
        if (op.includes('THRESHOLD')) return 'UPDATE_THRESHOLD';
        if (op.includes('TRANSFER ETH')) return 'TRANSFER_ETH';
        if (op.includes('TRANSFER TOKEN')) return 'TRANSFER_TOKEN';
        return 'EXECUTE_OPERATION';
    }

    private async broadcastBatch(rawTxs: string[]) {
        this.isBroadcastingBatch = true;
        this.batchTotal = rawTxs.length;
        this.batchCurrentIndex = 0;
        this.batchFinalReceipt = null;
        this.batchBroadcastStatuses = rawTxs.map(() => ({ status: 'pending' }));

        let lastReceipt: ethers.TransactionReceipt | null = null;
        const provider = this.contractService.getRpcProvider();
        let currentActivityId: string | null = null;

        try {
            for (let i = 0; i < rawTxs.length; i++) {
                this.batchCurrentIndex = i;
                this.batchBroadcastStatuses[i].status = 'broadcasting';
                currentActivityId = null;

                let rawTx = rawTxs[i].trim();

                if (rawTx.startsWith('{')) {
                    try {
                        const response = JSON.parse(rawTx);
                        if (response.rawTx) {
                            rawTx = response.rawTx;
                        } else if (response.data?.rawTx) {
                            rawTx = response.data.rawTx;
                        }
                    } catch (e) { }
                }

                if (!rawTx.startsWith('0x')) {
                    throw new Error(`Transaction ${i + 1} format invalid: must start with 0x`);
                }

                this.logger.debug(`[TxBroadcast] Broadcasting Tx ${i + 1}/${this.batchTotal}...`);
                const txResponse = await provider.broadcastTransaction(rawTx);

                this.batchBroadcastStatuses[i].hash = txResponse.hash;
                this.broadcastedTxHash = txResponse.hash; // update current hash for explorer link

                // Record Activity
                const txPayload = this.isBatchMode ? (this.unsignedTx as TxSignPayload[])[i] : (this.unsignedTx as TxSignPayload);
                const activityType = this.mapOperationToActivityType(txPayload?.metadata?.operation);
                currentActivityId = generateActivityId();
                const userAddress = txPayload?.from || txResponse.from || '0x0';
                
                try {
                    await this.activityService.addActivity({
                        id: currentActivityId,
                        timestamp: Date.now(),
                        type: activityType,
                        status: 'pending',
                        address: userAddress,
                        details: txPayload?.metadata?.args || { operation: txPayload?.metadata?.operation },
                        chainId: txPayload?.chainId || 1,
                        txHash: txResponse.hash,
                        txResponse: JSON.parse(JSON.stringify({
                            hash: txResponse.hash,
                            to: txResponse.to || undefined,
                            from: txResponse.from,
                            nonce: txResponse.nonce,
                            gasLimit: txResponse.gasLimit?.toString() || '0',
                            gasPrice: txResponse.gasPrice?.toString() || undefined,
                            data: txResponse.data || '0x',
                            value: txResponse.value?.toString() || '0',
                            chainId: txResponse.chainId,
                            type: txResponse.type || 0,
                            maxFeePerGas: txResponse.maxFeePerGas?.toString() || undefined,
                            maxPriorityFeePerGas: txResponse.maxPriorityFeePerGas?.toString() || undefined
                        }))
                    });
                } catch (actErr) {
                    this.logger.warn('Failed to record pending activity', actErr);
                }

                // Wait for confirmation
                lastReceipt = await txResponse.wait();

                if (lastReceipt) {
                    this.batchBroadcastStatuses[i].status = 'mined';
                    
                    // Update Activity
                    if (currentActivityId) {
                        try {
                            const gasUsed = lastReceipt.gasUsed?.toString() || '0';
                            const gasPrice = (lastReceipt as any).effectiveGasPrice?.toString() || txResponse.gasPrice?.toString() || '0';
                            const gasCost = ethers.formatEther(BigInt(gasUsed) * BigInt(gasPrice));
                            await this.activityService.updateActivityStatus(
                                currentActivityId,
                                lastReceipt.status === 1 ? 'success' : 'failed',
                                txResponse.hash,
                                undefined,
                                {
                                    txReceipt: JSON.parse(JSON.stringify({
                                        to: lastReceipt.to || undefined,
                                        from: lastReceipt.from,
                                        contractAddress: lastReceipt.contractAddress || undefined,
                                        transactionIndex: lastReceipt.index,
                                        gasUsed,
                                        blockHash: lastReceipt.blockHash || '',
                                        transactionHash: lastReceipt.hash,
                                        blockNumber: lastReceipt.blockNumber,
                                        confirmations: lastReceipt.confirmations,
                                        effectiveGasPrice: gasPrice,
                                        status: lastReceipt.status,
                                        type: lastReceipt.type
                                    })),
                                    blockNumber: lastReceipt.blockNumber,
                                    gasUsed,
                                    gasPrice,
                                    gasCost
                                }
                            );
                        } catch (actErr) {
                            this.logger.warn('Failed to update activity success', actErr);
                        }
                    }

                    // Force a small delay between transactions to ensure the RPC node has fully updated its state
                    // (especially allowances and nonces) before sending the next one.
                    if (i < rawTxs.length - 1) {
                        this.logger.debug(`[TxBroadcast] Waiting 2 seconds before next transaction...`);
                        await new Promise(resolve => setTimeout(resolve, 2000));
                    }
                } else {
                    throw new Error(`Transaction ${i + 1} receipt is null`);
                }
            }

            this.batchFinalReceipt = lastReceipt;

        } catch (e: any) {
            this.batchBroadcastStatuses[this.batchCurrentIndex].status = 'error';
            this.handleBroadcastError(e);
            
            if (currentActivityId) {
                try {
                    await this.activityService.updateActivityStatus(
                        currentActivityId,
                        'failed',
                        undefined,
                        { message: e.message || 'Transaction failed' }
                    );
                } catch (actErr) {}
            }
            // Allow user to cancel or retry from modal by not resolving interceptor immediately
        }
    }

    private handleBroadcastError(e: any) {
        this.logger.error('Broadcast error:', e);
        let userError = e.message || 'Unknown error';

        // Try to extract nested RPC error
        if (e.info && e.info.error && e.info.error.message) {
            userError = e.info.error.message;
        } else if (e.error && e.error.message) {
            userError = e.error.message;
        } else if (typeof e.message === 'string' && (e.message.includes('insufficient funds') || e.message.includes("enough funds to send tx"))) {
            userError = "Fonds insuffisants (ETH) sur le portefeuille qui diffuse la transaction pour payer les frais de gas.";
        }

        if (this.isBroadcastingBatch) {
            this.batchBroadcastStatuses[this.batchCurrentIndex].error = userError;
        }
        this.toastService.error(this.translate.instant('TX_BROADCAST.ERRORS.BROADCAST_FAILED') + ' ' + userError);
    }

    closeBatchModal(cancel: boolean = false) {
        this.isBroadcastingBatch = false;
        if (cancel) {
            this.goBack();
        }
    }

    isBatchComplete(): boolean {
        return this.batchBroadcastStatuses.length > 0 &&
            this.batchBroadcastStatuses.every(s => s.status === 'mined');
    }

    doneSingleTx() {
        if (this.broadcastedTxHash) {
            this.txInterceptor.resolveOfflineTransaction({ hash: this.broadcastedTxHash } as any);
            this.txInterceptor.clearCurrentUnsignedTx();
            this.location.back();
        } else {
            this.goBack();
        }
    }

    finishBroadcast() {
        this.isBroadcastingBatch = false;
        if (this.batchFinalReceipt) {
            this.txInterceptor.resolveOfflineTransaction(this.batchFinalReceipt);
        } else {
            this.goBack();
        }
    }

    goBack() {
        this.txInterceptor.resolveOfflineTransaction(null); // Cancel the pending transaction
        this.txInterceptor.clearCurrentUnsignedTx();
        this.location.back();
    }

    formatValue(value: string): string {
        if (!value || value === '0') return '0';
        try {
            return ethers.formatEther(value);
        } catch {
            return '0';
        }
    }

    formatGwei(value: string): string {
        if (!value || value === '0') return '0';
        try {
            return ethers.formatUnits(value, 'gwei');
        } catch {
            return '0';
        }
    }

    getExplorerUrl(): string {
        return this.getExplorerUrlForHash(this.broadcastedTxHash);
    }

    getExplorerUrlForHash(hash: string): string {
        if (!hash || !this.unsignedTx) return '';

        const chainId = this.isBatchMode && Array.isArray(this.unsignedTx)
            ? this.unsignedTx[0].chainId
            : (this.unsignedTx as TxSignPayload).chainId;
            
        if (chainId === 1) {
            return `https://etherscan.io/tx/${hash}`;
        } else if (chainId === 11155111) {
            return `https://sepolia.etherscan.io/tx/${hash}`;
        }
        return '';
    }

    ngOnDestroy(): void {
        this.logger.debug('[TxBroadcastComponent] destroyed');
    }
}
